            "msg_id": "M57",
            "speaker_id": 4315,
            "reply_to": null,
            "text": "Team, we've officially completed the first month since the full rollout. Great work getting us here! As part of T11, I've compiled a post-rollout review in A8, which includes our initial KPI performance and an improvement backlog based on site feedback. Please take a look.",
            "mentions": [
              436982
            ],
            "artifact_refs": [
              "A8",
              "T11"
            ],
            "decision_refs": [],
            "reactions": [
              {
                "emoji": "tada",
                "count": 2
              }
