            "artifact_refs": [],
            "decision_refs": [],
            "reactions": [
              {
                "emoji": "+1",
                "count": 1
              }
            ]
          },
          {
            "msg_id": "M46",
            "speaker_id": 455770,
            "reply_to": "M45",
            "text": "Great. Let's make that adjustment. Decision: We are officially revising the triage rules as discussed to better classify quick signature-based tasks. I'll update the process guide.",
