        "messages": [
          {
            "msg_id": "M11",
            "speaker_id": 58895,
            "reply_to": null,
            "text": "Hi team, I've created the first draft of the Staffing and Volunteer Recruitment Plan (A2) for the pilot. It outlines the roles we need for the first three events. Please take a look and let me know your thoughts on the number of volunteers and the proposed onboarding flow.",
            "mentions": [
