          {
            "msg_id": "M2",
            "speaker_id": 119847,
            "reply_to": "M1",
            "text": "Thanks for kicking this off. The objective is clear. Regarding scope, I think it's important to state what's *not* included. For example, are we changing the CRM tool itself, or just the process around it? We should make that explicit to manage stakeholder expectations.",
            "mentions": [
              83011
            ],
            "artifact_refs": [],
            "decision_refs": [],
            "reactions": [
              {
                "emoji": "heavy_plus_sign",
                "count": 2
