            "artifact_refs": [],
            "decision_refs": [],
            "reactions": []
          },
          {
            "msg_id": "M4",
            "speaker_id": 83011,
            "reply_to": "M2",
            "text": "Excellent point. Let's formalize that. D1: The scope is limited to the onboarding process and workspace. It does not include changes to the core CRM platform or post-onboarding support workflows. We can suggest improvements for those areas separately.",
            "mentions": [
              119847,
              98050
            ],
            "artifact_refs": [],
            "decision_refs": [
              "D1"
