            "decision_refs": [],
            "reactions": []
          },
          {
            "msg_id": "M47",
            "speaker_id": 511446,
            "reply_to": "M46",
            "text": "That's a great suggestion. Simple, clear language is essential to avoid causing anxiety for parents. We should go through the whole document and simplify the wording.",
            "mentions": [],
            "artifact_refs": [],
            "decision_refs": [],
            "reactions": [
