            "artifact_refs": [
              "A2"
            ],
            "decision_refs": [],
            "reactions": []
          },
          {
            "msg_id": "M17",
            "speaker_id": 321832,
            "reply_to": "M16",
            "text": "That's a good catch. I remember from my time as a mover, an unbalanced load is a real safety risk, especially with the forklift. The guide A2 should definitely include a check for weight distribution before moving off. This is a key part of T2.",
            "mentions": [
              36271
            ],
            "artifact_refs": [
              "A2",
              "T2"
