              "A6",
              "T12",
              "A8"
            ],
            "decision_refs": [],
            "reactions": [
              {
                "emoji": "tada",
                "count": 4
              }
            ]
          },
          {
            "msg_id": "M63",
            "speaker_id": 422937,
            "reply_to": "M62",
            "text": "Great result! From a logistics perspective, the check-in process was smooth, and we didn't have any scheduling conflicts. The pre-printed sign-in sheets from A6 worked well. One learning: Meeting Room 3 was a bit small for the most popular finance session.",
            "mentions": [],
            "artifact_refs": [
              "A6"
            ],
            "decision_refs": [],
            "reactions": []
          },
          {
            "msg_id": "M64",
            "speaker_id": 298367,
            "reply_to": "M62",
            "text": "The Sourdough Rye samples were gone in 30 minutes every day. The Spelt loaf was less popular. We should definitely feature the Sourdough again in future promotions.",
            "mentions": [],
            "artifact_refs": [],
            "decision_refs": [],
            "reactions": [
              {
                "emoji": "chart_with_upwards_trend",
                "count": 1
              }
            ]
